#!/usr/bin/env python3
# Code generated by AI.
"""Generate a configurable synthetic CNV dataset for smoke and integration tests.

The script creates a compact but structurally realistic dataset that approximates the
file formats expected by omniCNV:

- allele counts TSV with Chr/Pos/reference_tumor_count/alternative_tumor_count/Type/Chr_Allele/Alternative_Allele
- marker list used for filtering
- config.ini pointing to the generated files

The generation is intentionally parameterized so you can scale it up toward a more
realistic size when needed.
"""

from __future__ import annotations

import argparse
import configparser
import random
import time
from pathlib import Path
from typing import Iterable, List, Tuple

import numpy as np
import pandas as pd
import vcfpy


CNVRecord = Tuple[int, int, str, float]

HG38_CHROMOSOME_SIZES = {
    "chr1": 248_956_422,
    "chr2": 242_193_529,
    "chr3": 198_295_559,
    "chr4": 190_214_555,
    "chr5": 181_538_259,
    "chr6": 170_805_979,
    "chr7": 159_345_973,
    "chr8": 145_138_636,
    "chr9": 138_394_717,
    "chr10": 133_797_422,
    "chr11": 135_086_622,
    "chr12": 133_275_309,
    "chr13": 114_364_328,
    "chr14": 107_043_718,
    "chr15": 101_991_189,
    "chr16": 90_338_345,
    "chr17": 83_257_441,
    "chr18": 80_373_285,
    "chr19": 58_617_616,
    "chr20": 64_444_167,
    "chr21": 46_709_983,
    "chr22": 50_818_468,
    "chrX": 156_040_895,
}
CNV_STATES = ("A", "AA", "AAB", "AABB", "AAA")
CNV_FRACTIONS = (0.15, 0.5, 1.0)
CNV_FRACTIONS_K = (0.35, 0.5, 0.95)
TOTAL_MARKERS = 2_000_000
TOTAL_GENES = TOTAL_MARKERS // 75
HG38_CHR_Y_SIZE = 57_227_415


class _FileFormatHeaderLine(vcfpy.SimpleHeaderLine):
    """Represent the special VCF fileformat line for vcfpy."""

    @property
    def value(self):
        return self._value


class SyntheticVCFGenerator:
    """Generate allele-count rows from CNV records."""

    BASES = ("A", "C", "G", "T")
    STATES = {"AB", "A", "AA", "AAB", "AABB", "AAA"}

    def __init__(
        self,
        baseline_coverage: float = 30.0,
        baseline_vaf: float = 0.5,
        seed: int | None = None,
    ) -> None:
        if baseline_coverage <= 10:
            raise ValueError("baseline_coverage must be greater than 10")
        if abs(baseline_vaf - 0.5) > 0.05:
            raise ValueError("baseline_vaf must be around 0.5 for the AB state")
        self.baseline_coverage = float(baseline_coverage)
        self.baseline_vaf = baseline_vaf
        #self.generate_genomic_params = generate_genomic_params
        self.rng = random.Random(seed)

    def genomic_params(self, k: float, cnv: str) -> tuple[float, float]:
        """Return expected coverage ``m`` and allelic imbalance ``ai``."""
        if cnv not in self.STATES:
            raise ValueError(f"unsupported CNV state: {cnv}")
        if not 0 <= k <= 1:
            raise ValueError("k must be between 0 and 1")

        if cnv == "AB":
            m = self.baseline_coverage
            ai = 0.0
        elif cnv == "A":
            m = self.baseline_coverage * (2 - k) / 2
            ai = k / (2 * (2 - k))
        elif cnv == "AA":
            m = self.baseline_coverage
            ai = 2 * k / (2 * (1 + k))
        elif cnv == "AAB":
            m = self.baseline_coverage * (2 + k) / 2
            ai = k / (2 * (2 + k))
        elif cnv == "AABB":
            m = self.baseline_coverage * (2 + 2 * k) / 2
            ai = 0.0
        else:  # AAA
            m = self.baseline_coverage * (2 + k) / 2
            ai = 3 * k / (2 * (2 + k))

        if m <= 0:
            raise ValueError("generated coverage m must be positive")
        if not 0 <= ai <= 0.5:
            raise ValueError("generated ai must be between 0 and 0.5")
        return float(m), float(ai)

    def _draw_counts(self, m: float, ai: float) -> tuple[int, int, float]:
        expected_coverage = max(1.0, m * self.rng.gauss(1.0, 0.2))
        coverage_sd = 1.1 * (expected_coverage ** 0.5)
        coverage = max(1, int(round(self.rng.gauss(expected_coverage, coverage_sd))))
        sign = -1 if self.rng.randrange(2) else 1
        expected_vaf = 0.5 + sign * ai
        vaf_sd = 1.2 * (((0.5 + ai) * (0.5 - ai) / coverage) ** 0.5)
        vaf = min(1.0, max(0.0, self.rng.gauss(expected_vaf, vaf_sd*self.rng.gauss(1, 0.2))))
        alternative = int(round(vaf * coverage))
        return coverage - alternative, alternative, vaf

    def generate_rows(
        self,
        marker_positions: dict[str, list[int]],
        cnv_records: dict[str, list[CNVRecord]],
    ) -> list[dict]:
        """Return rows for markers, using AB outside the supplied CNV intervals."""
        rows = []
        for chrom, positions in marker_positions.items():
            regions = cnv_records.get(chrom, [])
            for pos in positions:
                cnv, k = "AB", 0.0
                for start, end, region_cnv, region_k in regions:
                    if start <= pos <= end:
                        cnv, k = region_cnv, region_k
                        break
                m, ai = self.genomic_params(k, cnv)
                reference, alternative, vaf = self._draw_counts(m, ai)
                ref = self.rng.choice(self.BASES)
                alt = self.rng.choice(tuple(base for base in self.BASES if base != ref))
                rows.append({
                    "CHROM": chrom,
                    "POS": pos,
                    "ID": ".",
                    "REF": ref,
                    "ALT": alt,
                    "QUAL": ".",
                    "FILTER": "PASS",
                    "INFO": ".",
                    "FORMAT": "AD",
                    "SAMPLE": f"{reference},{alternative}",
                    "reference_tumor_count": reference,
                    "alternative_tumor_count": alternative,
                    "ai": ai,
                    "vaf": vaf,
                    "CNV": cnv,
                    "k": k,
                })
        return rows


def write_minimal_vcf(rows: Iterable[dict], output_path: Path, sample_name: str = "SAMPLE") -> Path:
    """Serialize rows with only the header required by VCF readers."""
    header = vcfpy.Header(
        lines=[_FileFormatHeaderLine("fileformat", "VCFv4.3", {"ID": "fileformat"})],
        samples=vcfpy.SamplesInfos([sample_name]),
    )
    header.add_format_line({
        "ID": "AD",
        "Number": "R",
        "Type": "Integer",
        "Description": "Reference and alternative allele depths",
    })
    with vcfpy.Writer.from_path(str(output_path), header) as writer:
        for row in rows:
            writer.write_record(vcfpy.Record(
                CHROM=row["CHROM"],
                POS=row["POS"],
                ID=[row["ID"]],
                REF=row["REF"],
                ALT=[vcfpy.Substitution(type_="SNV", value=row["ALT"])],
                QUAL=None,
                FILTER=[row["FILTER"]],
                INFO={},
                FORMAT=["AD"],
                calls=[vcfpy.Call(sample_name, {"AD": [
                    row["reference_tumor_count"],
                    row["alternative_tumor_count"],
                ]})],
            ))
    return output_path


def allocate_counts(chromosome_sizes: dict[str, int], total: int) -> dict[str, int]:
    """Allocate an exact total proportionally to chromosome lengths."""
    genome_size = sum(chromosome_sizes.values())
    counts = {chrom: int(total * size / genome_size) for chrom, size in chromosome_sizes.items()}
    remainder = total - sum(counts.values())
    for chrom in sorted(chromosome_sizes, key=chromosome_sizes.get, reverse=True)[:remainder]:
        counts[chrom] += 1
    return counts


def generate_marker_positions(
    chromosome_sizes: dict[str, int], total_markers: int, rng: random.Random
) -> dict[str, list[int]]:
    """Place unique markers uniformly at random across hg38 chromosomes."""
    counts = allocate_counts(chromosome_sizes, total_markers)
    return {
        chrom: sorted(rng.sample(range(1, size + 1), counts[chrom]))
        for chrom, size in chromosome_sizes.items()
    }


def intervals_overlap(first: CNVRecord, second: CNVRecord) -> bool:
    return first[0] <= second[1] and second[0] <= first[1]


def generate_cnv_records(
    chromosome_sizes: dict[str, int], rng: random.Random
) -> dict[str, list[CNVRecord]]:
    """Place all requested CNV combinations and discard intersecting candidates randomly."""
    candidates = [(fraction, k, cnv) for fraction in CNV_FRACTIONS for k in CNV_FRACTIONS_K for cnv in CNV_STATES]
    rng.shuffle(candidates)
    records = {chrom: [] for chrom in chromosome_sizes}
    for fraction, k, cnv in candidates:
        chrom = rng.choice(tuple(chromosome_sizes))
        chromosome_size = chromosome_sizes[chrom]
        arm_size = chromosome_size // 2
        arm_start = 1 if rng.randrange(2) == 0 else arm_size + 1
        arm_end = arm_start + arm_size - 1
        length = max(1, int(round(arm_size * fraction)))
        if length > arm_end - arm_start + 1:
            length = arm_end - arm_start + 1
        start = rng.randint(arm_start, arm_end - length + 1)
        candidate = (start, start + length - 1, cnv, k)
        if any(intervals_overlap(candidate, existing) for existing in records[chrom]):
            continue
        records[chrom].append(candidate)
    for chrom in records:
        records[chrom].sort()
    return records


def generate_allele_counts(
    rows: list[dict],
) -> pd.DataFrame:
    """Convert generated VCF-style rows to the configured allele-count TSV."""
    return pd.DataFrame({
        "Chr": [row["CHROM"] for row in rows],
        "Pos": [row["POS"] for row in rows],
        "reference_tumor_count": [row["reference_tumor_count"] for row in rows],
        "alternative_tumor_count": [row["alternative_tumor_count"] for row in rows],
        "Type": "SNP",
        "Chr_Allele": [row["REF"] for row in rows],
        "Alternative_Allele": [row["ALT"] for row in rows],
    })


def write_marker_list(allele_counts: pd.DataFrame, output_dir: Path) -> pd.DataFrame:
    markers = allele_counts[["Chr", "Pos"]].drop_duplicates().reset_index(drop=True)
    markers.to_csv(output_dir / "markerslist.tsv", sep="\t", index=False, header=False)
    return markers


def write_config(output_dir: Path, output_prefix: str, include_gene_count: bool = False) -> Path:
    config = configparser.ConfigParser()
    config["FILES"] = {
        "markerslist": str((output_dir / "markerslist.tsv").resolve()),
        "arms": str((output_dir / "arms.tsv").resolve()),
        "cyto": str((output_dir / "cyto.tsv").resolve()),
    }
    config["VCF_FORMAT"] = {
        "chrom_field": "0",
        "position_field": "1",
        "ref_field": "3",
        "alt_field": "4",
        "tag_name_field": "8",
        "tag_field": "9",
    }
    if include_gene_count:
        config["GENE_COUNT"] = {"geneID": "geneID", "count": "count", "cpm_thr": "1"}
    config["ALLELIC_COUNT_FORMAT"] = {
        "Chr": "Chr",
        "Pos": "Pos",
        "ref_cts": "reference_tumor_count",
        "alt_cts": "alternative_tumor_count",
        "Type": "Type",
        "ref": "Chr_Allele",
        "alt": "Alternative_Allele",
    }
    config["PERFORMANCE"] = {"chunksize": "2000000", "min_markers": "50000"}
    config["ARMS"] = {"excluded_arms": "chr22p,chr15p,chr21p,chrYp"}
    config["AC_FILTER"] = {
        "HOthr": "0.95",
        "PTMthr": "0.01",
        "cvthr": "10",
    }
    config["SEGMENTATION"] = {
        "min_markers_for_seg": "200",
        "gc_p0": "0.96",
        "gc_length": "51",
        "gc_ms": "1",
        "ac_p0": "0.96",
        "ac_length": "51",
        "ac_ms": "1",
        "ac_thr": "1",
        "gc_thr": "1",
        "absolute_counts_threshold": "0.2",
    }
    config["KARYOTYPING"] = {
        "max_dip_ai": "0.02",
        "initial_scale": "2",
        "DUP_MAD_thr": "3",
        "MIN_SIZE": "10",
    }
    config["chrY"] = {
        "PAR": "((0, 2781479), (26600001, 57217415))",
        "vaf_min": "0.98",
    }

    config_path = output_dir / f"{output_prefix}.config.ini"
    with config_path.open("w", encoding="utf-8") as handle:
        config.write(handle)
    return config_path


def build_arms_file(chromosome_sizes: dict[str, int], output_dir: Path) -> pd.DataFrame:
    rows = [
        {"Chr": chrom, "Boundry": size // 2, "Name": f"{chrom}p"}
        for chrom, size in chromosome_sizes.items()
    ]
    df = pd.DataFrame(rows)
    df.to_csv(output_dir / "arms.tsv", sep="\t", index=False)
    return df


def build_cytoband_file(chromosome_sizes: dict[str, int], output_dir: Path) -> pd.DataFrame:
    cytoband_sizes = {**chromosome_sizes, "chrY": HG38_CHR_Y_SIZE}
    df = pd.DataFrame([
        {
            "chrom": chrom,
            "chromStart": 0,
            "chromEnd": size,
            "name": f"{chrom}q11",
            "gieStain": "gneg",
        }
        for chrom, size in cytoband_sizes.items()
    ])
    df.to_csv(output_dir / "cyto.tsv", sep="\t", index=False)
    return df


def write_cnv_truth(cnv_records: dict[str, list[CNVRecord]], output_dir: Path) -> Path:
    rows = []
    for chrom, records in cnv_records.items():
        for start, end, cnv, k in records:
            rows.append({"chrom": chrom, "start": start, "end": end, "CNV": cnv, "k": k})
    truth_path = output_dir / "cnv_truth.tsv"
    pd.DataFrame(rows).sort_values(["chrom", "start"]).to_csv(truth_path, sep="\t", index=False)
    return truth_path


def load_cnv_truth(truth_path: Path) -> dict[str, list[CNVRecord]]:
    """Load chromosome-local CNV records from a previous truth file."""
    truth = pd.read_csv(truth_path, sep="\t")
    return {
        chrom: list(zip(
            group["start"].astype(int),
            group["end"].astype(int),
            group["CNV"],
            group["k"].astype(float),
        ))
        for chrom, group in truth.groupby("chrom", sort=False)
    }


def make_reference_panel(
    chromosome_sizes: dict[str, int], total_genes: int, rng: np.random.Generator
) -> pd.DataFrame:
    """Generate uniformly placed genes with log-uniform reference abundance."""
    position_rng = random.Random(int(rng.integers(0, 2**32)))
    positions = generate_marker_positions(chromosome_sizes, total_genes, position_rng)
    rows = []
    gene_id = 1
    for chrom, chrom_positions in positions.items():
        arm_size = chromosome_sizes[chrom] // 2
        for pos in chrom_positions:
            rows.append({
                "geneID": f"gene_{gene_id}",
                "arm": f"{chrom}{'p' if pos <= arm_size else 'q'}",
                "refcpm": 10 ** rng.uniform(1, 5),
                "Pos": pos,
            })
            gene_id += 1
    return pd.DataFrame(rows)


def generate_gene_counts(
    reference_panel: pd.DataFrame,
    cnv_records: dict[str, list[CNVRecord]],
    generator: SyntheticVCFGenerator,
    rng: np.random.Generator,
) -> pd.DataFrame:
    """Generate RNA counts using state-adjusted reference abundance."""
    counts = []
    for gene in reference_panel.itertuples(index=False):
        cnv_state, k = "AB", 0.0
        for start, end, region_cnv, region_k in cnv_records.get(gene.arm[:-1], []):
            if start <= gene.Pos <= end:
                cnv_state, k = region_cnv, region_k
                break
        m, _ = generator.genomic_params(k, cnv_state)
        copy_number = 2 * m / generator.baseline_coverage
        effect = 1 + 1.0 * ((copy_number - 2) / 2)
        expected_count = gene.refcpm * effect
        counts.append(int(round(rng.normal(expected_count, 10 * np.sqrt(expected_count)))))
    return pd.DataFrame({"geneID": reference_panel["geneID"], "count": counts})


def main() -> None:
    parser = argparse.ArgumentParser(description="Generate a configurable synthetic omniCNV dataset.")
    parser.add_argument("--output-dir", type=Path, default=Path("tests/fixtures/generated"), help="Directory to write synthetic files into.")
    parser.add_argument("--prefix", default="synthetic", help="Prefix for generated files.")
    parser.add_argument("--rna", action="store_true", help="Also generate an RNA reference panel and gene counts.")
    parser.add_argument("--truth-cnv", type=Path, help="Reuse CNV truth from a previous generated dataset.")
    args = parser.parse_args()

    seed = int(time.time() * 1000)
    rng = random.Random(seed)
    output_dir = args.output_dir
    output_dir.mkdir(parents=True, exist_ok=True)

    marker_positions = generate_marker_positions(HG38_CHROMOSOME_SIZES, TOTAL_MARKERS, rng)
    cnv_records = load_cnv_truth(args.truth_cnv) if args.truth_cnv else generate_cnv_records(HG38_CHROMOSOME_SIZES, rng)
    generator = SyntheticVCFGenerator(seed=seed)
    vcf_rows = generator.generate_rows(marker_positions, cnv_records)
    allele_counts = generate_allele_counts(vcf_rows)
    allele_counts.to_csv(output_dir / f"{args.prefix}_allele_counts.tsv", sep="\t", index=False)
    write_minimal_vcf(vcf_rows, output_dir / f"{args.prefix}.vcf")

    write_marker_list(allele_counts, output_dir)
    write_cnv_truth(cnv_records, output_dir)
    build_arms_file(HG38_CHROMOSOME_SIZES, output_dir)
    build_cytoband_file(HG38_CHROMOSOME_SIZES, output_dir)

    if args.rna:
        numpy_rng = np.random.default_rng(seed)
        reference_panel = make_reference_panel(HG38_CHROMOSOME_SIZES, TOTAL_GENES, numpy_rng)
        reference_panel.to_csv(output_dir / f"{args.prefix}_reference_panel.tsv", sep="\t", index=False)
        gene_counts = generate_gene_counts(reference_panel, cnv_records, generator, numpy_rng)
        gene_counts.to_csv(output_dir / f"{args.prefix}_gene_counts.tsv", sep="\t", index=False)

    write_config(output_dir, args.prefix, include_gene_count=args.rna)

    print(f"Generated synthetic dataset in {output_dir}")
    print(f"Allele counts rows: {len(allele_counts)}")
    print(f"CNV regions: {sum(len(records) for records in cnv_records.values())}")
    if args.rna:
        print(f"Reference genes: {len(reference_panel)}")
    print(f"Seed: {seed}")
    print(f"Config file: {output_dir / f'{args.prefix}.config.ini'}")


if __name__ == "__main__":
    main()
